  "decode.kind.version.title": "Versão",
  "decode.kind.version.desc": "Geração / versão de lançamento da família.",
  "decode.kind.params.title": "Número de parâmetros",
  "decode.kind.params.desc": "Total de parâmetros (bilhões). Determina a qualidade e a VRAM — maior = mais capaz, porém mais pesado.",
  "decode.kind.paramsM.title": "Número de parâmetros (M)",
  "decode.kind.paramsM.desc": "Milhões de parâmetros — um modelo pequeno / próprio para edge.",
  "decode.kind.moe.title": "Mistura de especialistas",
  "decode.kind.moe.desc": "especialistas × tamanho de cada um (ex.: 8x7B). Só alguns especialistas rodam por token (computação rápida), mas TODOS os especialistas precisam caber na VRAM.",
  "decode.kind.moeActive.title": "MoE — parâmetros ativos",
  "decode.kind.moeActive.desc": "Parâmetros ativos por token (ex.: A3B = 3B ativos). Computação ≈ parâmetros ativos; VRAM ≈ parâmetros totais.",
  "decode.kind.quantAWQ.title": "Quantização · AWQ",
  "decode.kind.quantAWQ.desc": "Activation-aware Weight Quantization (quantização de pesos sensível às ativações, ~4 bits). ~4× menor, rápida na GPU, pequena perda de acurácia.",
  "decode.kind.quantGPTQ.title": "Quantização · GPTQ",
  "decode.kind.quantGPTQ.desc": "Quantização de pesos GPTQ de 4 bits. Pequena e rápida na GPU; leve perda de acurácia.",
  "decode.kind.quantGGUF.title": "Formato · GGUF",
  "decode.kind.quantGGUF.desc": "Formato do llama.cpp — roda em CPU e GPU com vários níveis de quantização (Q4…Q8). Ótimo para uso local / Mac.",
  "decode.kind.quantFP8.title": "Quantização · FP8",
  "decode.kind.quantFP8.desc": "Ponto flutuante de 8 bits. ~2× menor que BF16, quase sem perda, rápido em GPUs modernas (Hopper/Blackwell/MI300).",
  "decode.kind.quantNVFP4.title": "Quantização · NVFP4 / MXFP4",
  "decode.kind.quantNVFP4.desc": "Ponto flutuante de 4 bits (NVFP4 na Blackwell, MXFP4 por exemplo no gpt-oss). ~4× menor, com acurácia melhor que INT4.",
  "decode.kind.quantINT.title": "Quantização · INT4/INT8",
  "decode.kind.quantINT.desc": "Quantização inteira (4 ou 8 bits). Menor e mais rápida; INT4 sacrifica um pouco de acurácia.",
  "decode.kind.quantWA.title": "Quantização · bits W/A",
  "decode.kind.quantWA.desc": "Largura em bits dos pesos (W, de weights) e das ativações (A) — ex.: W4A16 = pesos de 4 bits, ativações de 16 bits.",
  "decode.kind.quantBnb.title": "Quantização · bitsandbytes",
  "decode.kind.quantBnb.desc": "Quantização feita na hora, em 4 bits / 8 bits (bitsandbytes). Fácil de carregar, boa para VRAM limitada.",
  "decode.kind.quantDynamic.title": "Quantização · dinâmica",
  "decode.kind.quantDynamic.desc": "Quantização dinâmica — escalas calculadas em tempo de execução (muitas vezes combinada com FP8).",
  "decode.kind.precision.title": "Precisão",
  "decode.kind.precision.desc": "Precisão nativa dos pesos (BF16/FP16 = 2 bytes, FP32 = 4). Qualidade total, maior tamanho.",
  "decode.kind.instruct.title": "Ajustado por instrução",
  "decode.kind.instruct.desc": "Passou por ajuste fino para seguir instruções / conversar. Use-o para assistentes e para a maioria das tarefas.",
  "decode.kind.chat.title": "Ajustado para chat",
  "decode.kind.chat.desc": "Otimizado para conversas de vários turnos.",
  "decode.kind.base.title": "Modelo base",
  "decode.kind.base.desc": "Apenas pré-treinado — NÃO ajustado por instrução. Serve para ajuste fino, não para conversar direto.",
  "decode.kind.coder.title": "Especializado em código",
