  "decode.kind.math.title": "Especializado em matemática",
  "decode.kind.math.desc": "Ajustado para raciocínio matemático.",
  "decode.kind.vision.title": "Visão / multimodal",
  "decode.kind.vision.desc": "Aceita imagens + texto (VLM).",
  "decode.kind.embedding.title": "Embeddings",
  "decode.kind.embedding.desc": "Produz vetores para busca / RAG — não é um modelo de chat.",
  "decode.kind.reranker.title": "Reranker",
